const { Library } = require('./s1_library.js');
const { Cache } = require('./s7_cache.js');

function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

module.exports = { shelfLine };

// Test asserts
const library1 = new Library();
console.assert(shelfLine(library1) === '(empty)', "Test 1 failed: Empty library should return '(empty)'");

library1.addBook("978-0134685991", "Effective Java", 3);
console.assert(shelfLine(library1) === "Effective Java", "Test 2 failed: Single book should return title");

library1.addBook("978-0201633610", "Design Patterns", 1);
const result = shelfLine(library1);
const expected = "Design Patterns, Effective Java";
console.assert(result === expected, `Test 3 failed: Multiple books should be sorted and joined. Got: "${result}", Expected: "${expected}"`);

console.log("All asserts passed!");

